/* WebTorrent browser server (classic service worker).
 * waitUntil() is required so Firefox does not mark the worker active
 * before this page is actually controlled — otherwise /webtorrent/* hits the origin and 404s.
 */
'use strict'

let cancellable = false
const portTimeoutDuration = 5000

self.addEventListener('install', event => {
  event.waitUntil(self.skipWaiting())
})

self.addEventListener('activate', event => {
  event.waitUntil(self.clients.claim())
})

self.addEventListener('fetch', event => {
  const response = handleFetch(event)
  if (response) event.respondWith(response)
})

function handleFetch (event) {
  const { url } = event.request
  const prefix = self.registration.scope + 'webtorrent/'
  if (!url.includes(prefix)) return null
  if (url.includes(prefix + 'keepalive/')) return new Response()
  if (url.includes(prefix + 'cancel/')) {
    return new Response(new ReadableStream({
      cancel () {
        cancellable = true
      }
    }))
  }
  return serve(event)
}

async function serve ({ request }) {
  const { url, method, headers, destination } = request
  const clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })

  const [data, port] = await new Promise(resolve => {
    for (const client of clientList) {
      const { port1, port2 } = new MessageChannel()
      port1.onmessage = ({ data }) => {
        resolve([data, port1])
      }
      client.postMessage({
        url,
        method,
        headers: Object.fromEntries(headers.entries()),
        scope: self.registration.scope,
        destination,
        type: 'webtorrent'
      }, [port2])
    }
  })

  let timeOut = null
  const cleanup = () => {
    port.postMessage(false)
    clearTimeout(timeOut)
    port.onmessage = null
  }

  if (data.body !== 'STREAM') {
    cleanup()
    return new Response(data.body, data)
  }

  return new Response(new ReadableStream({
    pull (controller) {
      return new Promise(resolve => {
        port.onmessage = ({ data }) => {
          if (data) {
            controller.enqueue(data)
          } else {
            cleanup()
            controller.close()
          }
          resolve()
        }
        // Firefox cannot cancel ReadableStreams in a service worker.
        if (!cancellable) {
          clearTimeout(timeOut)
          if (destination !== 'document') {
            timeOut = setTimeout(() => {
              cleanup()
              resolve()
            }, portTimeoutDuration)
          }
        }
        port.postMessage(true)
      })
    },
    cancel () {
      cleanup()
    }
  }), data)
}
